input.content:
package main

import (
	"fmt"

	"github.com/caddyserver/caddy/v2/caddyconfig/caddyfile"
)

func main() {
	for _, in := range []string{
		"uri replace \"\\}\" %7D",
		"uri replace \"\\{\" %7B",
		"uri replace \\} %7D",
		"uri replace \\{ %7B",
		"uri replace \"}\" %7D",
	} {
		tokens, err := caddyfile.Tokenize([]byte(in), "Caddyfile")
		fmt.Printf("%-30q => %v err=%v\n", in, tokens, err)
	}
}

